SELECT p.id as id,p.title AS title, c.content as content,c.page_id as page_id FROM wiki_page p JOIN wiki_content c ON p.last_ver = c.version AND p.id = c.page_id JOIN wiki w ON w.prj_id = #{id} AND p.wiki_id = w.id
WHERE p.title = #{title}
AND p.title = w.start_page

	select count(*)
		from wiki_page p
        join wiki w
        on w.id = p.wiki_id
		where w.prj_id = #{id}
		and title=#{name}
